mapper.select:
SELECT r.*, s.name AS store_name, u.nickname AS create_by_name
FROM ecom_amz_report r
LEFT JOIN ecom_store s ON s.id = r.store_id
LEFT JOIN sys_user u ON u.id = r.create_by

    r.store_id = #{storeId}
    AND r.report_type = #{reportType}
    AND r.status = #{status}

ORDER BY r.id DESC
